/**
 * Auto-instrumentation event catalog.
 *
 * Generated by cro. Maintained by the agent on every push — when behavior
 * changes (handler text, element type), the event definitions update so
 * your PostHog taxonomy stays aligned with what the UI actually does.
 *
 * Usage:
 *   import { capture, type CroEvent } from './events';
 *   capture('checkout_button_clicked', { source_file: '...' });
 */

