export type CroEventName = keyof typeof EVENTS;
export type CroEventProps<K extends CroEventName> = z.infer<(typeof EVENTS)[K]>;

/**
 * Type-safe wrapper around your analytics provider's capture call.
 * Generated against the provider detected in package.json. Adjust if needed.
 */
export type CroEvent = {
  [K in CroEventName]: { name: K; props: CroEventProps<K> };
}[CroEventName];

export function capture<K extends CroEventName>(name: K, props: CroEventProps<K>): void {
  // Validate at the boundary so a typo can't ship to PostHog.
  EVENTS[name].parse(props);
  if (typeof window !== 'undefined' && (window as unknown as { posthog?: { capture: (n: string, p: unknown) => void } }).posthog) {
    (window as unknown as { posthog: { capture: (n: string, p: unknown) => void } }).posthog.capture(name, props);
  }
}
